from docx import Document
from docx.shared import Pt, Cm, Inches
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.section import WD_SECTION
from pathlib import Path

root=Path(__file__).parent
reports=root/'docs'/'reports'
items=[
(6,'Заместитель (Proxy)','Паттерн Proxy предоставляет объект-заместитель, который контролирует доступ к реальному объекту. В игре «Змейка» заместитель SettingsProxy реализует интерфейс ISettingsStore и проверяет право записи и допустимость интервала обновления до передачи операции классу SettingsStore.','ISettingsStore — общий интерфейс хранилища. SettingsStore хранит настройки. SettingsProxy проверяет доступ и диапазон TickMilliseconds (50–1000 мс), после чего делегирует сохранение реальному объекту. В Main создаётся хранилище и прокси с разрешением записи, загружается настройка, меняется интервал и выполняется сохранение.','Проверка доступа и валидация настроек отделены от самого хранилища. При необходимости можно добавить роли пользователя или журналирование, не изменяя SettingsStore.','SettingsProxy, ISettingsStore, SettingsStore'),
(7,'Команда (Command), Итератор (Iterator)','Command инкапсулирует действие в отдельном объекте. Iterator предоставляет последовательный доступ к элементам коллекции без раскрытия способа её хранения. В игре команды управления и перемещения представлены объектами, а сегменты змейки обходятся отдельным итератором.','Интерфейс IGameCommand определяет Execute(SnakeGame). TurnCommand меняет направление, MoveCommand выполняет шаг. CommandQueue хранит команды и последовательно запускает их. SnakeIterator хранит ссылку на список сегментов и текущий индекс; HasNext сообщает о наличии следующего элемента, Next возвращает его.','Команды можно накапливать, менять порядок и повторно использовать. Итератор скрывает детали обхода списка сегментов змейки.','IGameCommand, TurnCommand, MoveCommand, CommandQueue, SnakeIterator'),
(8,'Цепочка обязанностей (Chain of Responsibility)','Цепочка обязанностей передаёт запрос последовательно связанным обработчикам. Каждый обработчик либо принимает решение, либо передаёт запрос следующему. Для игры «Змейка» это удобно при проверке столкновений.','Базовый CollisionHandler содержит ссылку next и метод Handle. WallCollisionHandler проверяет выход за границы игрового поля. BodyCollisionHandler проверяет пересечение с телом змейки. В демонстрации обработчики соединяются методом SetNext, после чего проверяют предполагаемую позицию головы.','Проверки разделены на независимые классы. Новое правило (например, столкновение с препятствием) можно добавить в цепочку без переписывания существующих обработчиков.','CollisionHandler, WallCollisionHandler, BodyCollisionHandler'),
(9,'Посредник (Mediator), Снимок (Memento)','Mediator централизует взаимодействие компонентов, уменьшая количество прямых связей между ними. Memento сохраняет состояние объекта и позволяет восстановить его позднее. В игре посредник уведомляет интерфейсное табло и звуковой компонент об изменении счёта, а снимок хранит состояние игрового поля.','IGameComponent задаёт метод OnScoreChanged. GameMediator хранит зарегистрированные компоненты и рассылает им уведомления. GameMemento содержит копию тела змейки, еду, направление, счёт и состояние игры. GameSnapshot.Save создаёт снимок, а Restore восстанавливает данные.','Компоненты игры не знают друг о друге и взаимодействуют через посредника. Снимок позволяет реализовать отмену хода, контрольные точки или восстановление после ошибки.','GameMediator, IGameComponent, GameMemento, GameSnapshot'),
(10,'Наблюдатель (Observer), Состояние (State)','Observer определяет зависимость «один ко многим»: при изменении объекта все подписчики получают уведомление. State выносит поведение, зависящее от текущего состояния, в отдельные классы. В «Змейке» наблюдатели получают игровые события, а состояния определяют, выполняется ли игровой ход.','GameEventSource хранит подписчиков IGameObserver и вызывает Update для каждого. ConsoleObserver выводит полученное сообщение. Интерфейс IGameState определяет Handle и Name. PlayingState выполняет ход, PausedState блокирует ход, GameOverState сообщает о завершении. GameStateContext переключает текущее состояние.','Observer позволяет подключать табло, журнал и звуковые уведомления без изменения источника событий. State исключает множество условных операторов при обработке игрового цикла.','GameEventSource, IGameObserver, ConsoleObserver, IGameState, PlayingState, PausedState, GameOverState'),
(11,'Стратегия (Strategy), Шаблонный метод (Template Method)','Strategy позволяет выбирать один из взаимозаменяемых алгоритмов. Template Method задаёт общий порядок выполнения алгоритма, оставляя отдельные шаги подклассам. В игре можно выбирать правила перемещения змейки и единый порядок обработки кадра.','IMovementStrategy задаёт метод Next. BoundedMovement перемещает голову без перехода через границу, WrapMovement переносит её на противоположную сторону поля. GameLoopTemplate задаёт последовательность ReadInput, Update, Render. DemoGameLoop реализует конкретные шаги.','Алгоритм перемещения можно заменить во время работы, не меняя игровой объект. Общая структура кадра остаётся одинаковой, а детали шагов можно переопределять.','IMovementStrategy, BoundedMovement, WrapMovement, GameLoopTemplate, DemoGameLoop'),
(12,'Архитектурный паттерн MVC','MVC разделяет приложение на Model, View и Controller. Model хранит данные и бизнес-логику, View отвечает за представление данных, Controller принимает действия пользователя и связывает остальные части.','SnakeModel предоставляет операции изменения модели игры. SnakeView выводит счёт и координаты головы змейки. SnakeController принимает направление, вызывает методы модели и затем обновляет представление. В демонстрации контроллер получает направление Up и отображает результат.','Разделение обязанностей упрощает сопровождение и замену интерфейса. Логику игры можно тестировать отдельно от способа вывода информации.','SnakeModel, SnakeView, SnakeController'),
(13,'Паттерн CQRS','CQRS разделяет операции изменения состояния (Command) и операции чтения (Query). Команды выражают намерение изменить данные, а запросы возвращают информацию без изменения состояния. Для примера используется подсистема игрового счёта.','AddScoreCommand содержит количество начисляемых очков. ScoreCommandHandler обрабатывает команду и изменяет счёт. ScoreQueryService предоставляет метод чтения текущего значения и не изменяет данные. В Main последовательно начисляются очки, затем выполняется запрос.','Разделение чтения и записи делает назначение операций явным. В крупной системе чтение и запись можно масштабировать и оптимизировать независимо. В учебном примере оба механизма используют один источник данных.','AddScoreCommand, ScoreCommandHandler, ScoreQueryService'),
(14,'Паттерн Repository','Repository отделяет бизнес-логику от конкретного способа хранения данных и предоставляет интерфейс, похожий на коллекцию объектов. В игре репозиторий используется для сохранения и получения рекордов игроков.','IRecordRepository объявляет Save и Find. InMemoryRecordRepository реализует хранение в Dictionary. Метод Save обновляет рекорд только если новый результат выше сохранённого. Метод Find возвращает запись игрока либо null, если запись отсутствует.','Игровой код зависит от интерфейса репозитория, а не от конкретной коллекции. В дальнейшем реализацию можно заменить на файловое или SQL-хранилище без изменения клиентского кода.','IRecordRepository, InMemoryRecordRepository, PlayerRecord'),
(15,'Producer-Consumer (Производитель–Потребитель)','Producer-Consumer организует обмен задачами между производителями и потребителями через потокобезопасную очередь. Производитель добавляет задачи, потребитель извлекает и выполняет их. В игре этот механизм подходит для фонового сохранения рекордов и записи событий.','BackgroundTaskQueue использует BlockingCollection<Action>. При создании объекта запускается фоновая задача-потребитель, которая перебирает очередь через GetConsumingEnumerable. Метод Produce добавляет действие. Stop вызывает CompleteAdding и ожидает завершения обработки очереди.','Фоновые операции не блокируют основной поток приложения. BlockingCollection обеспечивает безопасную передачу задач между потоками и корректное завершение потребителя.','BackgroundTaskQueue, BlockingCollection<Action>, Task')]

for n,title,theory,impl,conclusion,classes in items:
    d=Document()
    sec=d.sections[0]; sec.top_margin=Cm(2); sec.bottom_margin=Cm(2); sec.left_margin=Cm(3); sec.right_margin=Cm(1.5)
    style=d.styles['Normal']; style.font.name='Times New Roman'; style.font.size=Pt(14)
    for s in ['МИНИСТЕРСТВО НАУКИ И ВЫСШЕГО ОБРАЗОВАНИЯ РФ','ФГАОУ ВО «СЕВЕРО-КАВКАЗСКИЙ ФЕДЕРАЛЬНЫЙ УНИВЕРСИТЕТ»','Институт информационных технологий и кибербезопасности','Межинститутская базовая кафедра']:
        p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run(s).bold=True
    for _ in range(4): d.add_paragraph('')
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run('ОТЧЕТ ПО ЛАБОРАТОРНОЙ РАБОТЕ № '+str(n)).bold=True
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run('Дисциплина: Паттерны проектирования')
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run('Тема: '+title)
    for _ in range(3): d.add_paragraph('')
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    p.add_run('Выполнил: Смакуев Ренат Арсеньевич\n4 курс, группа ПИЖ-б-о-23-2(2)\n09.03.04 «Программная инженерия»\n\nПроверил: ассистент МБК ИИТиКБ Белик А. И.')
    for _ in range(3): d.add_paragraph('')
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run('Ставрополь, 2026 г.')
    d.add_page_break()
    d.add_heading('Цель работы', level=1)
    d.add_paragraph('Получить практические навыки применения паттерна(ов) проектирования '+title+' при разработке приложения «Игра Змейка» (вариант 10) на языке C#.')
    d.add_heading('1. Теоретическое обоснование', level=1); d.add_paragraph(theory)
    d.add_heading('2. Проектирование и реализация', level=1)
    d.add_paragraph('Вариант 10: разработка приложения «Игра Змейка». Реализация выполнена на языке C# в проекте SnakeLabs для Visual Studio (.NET Framework 4.8).')
    d.add_paragraph(impl)
    d.add_paragraph('Основные классы и интерфейсы: '+classes+'.')
    d.add_heading('3. UML-диаграмма классов', level=1)
    diagram = root/'docs'/'uml'/'png'/({6:'LR06_Proxy',7:'LR07_Command_Iterator',8:'LR08_Chain',9:'LR09_Mediator_Memento',10:'LR10_Observer_State',11:'LR11_Strategy_Template',12:'LR12_MVC',13:'LR13_CQRS',14:'LR14_Repository',15:'LR15_ProducerConsumer'}[n]+'.png')
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p.add_run().add_picture(str(diagram), width=Inches(6.0))
    p=d.add_paragraph('Рисунок 1 — Диаграмма классов лабораторной работы № '+str(n)); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    d.add_heading('4. Результат работы программы', level=1)
    d.add_paragraph('Работа паттерна демонстрируется в консольном приложении. При запуске выводится отдельный раздел для каждой лабораторной работы; в разделе отображаются ключевые действия объектов и результат выполнения сценария.')
    d.add_paragraph('Исходный код находится в файле src/Program.cs. UML-диаграмма приведена в каталоге docs/uml.')
    d.add_heading('Вывод', level=1); d.add_paragraph('В ходе лабораторной работы № '+str(n)+' рассмотрен и реализован паттерн(ы) «'+title+'» на примере игры «Змейка». '+conclusion)
    d.save(reports/f'Отчет_ЛР{n:02d}_Вариант10_CSharp.docx')

# Markdown report index
md=['# Отчёты по лабораторным работам № 6–15','', 'Вариант 10 — игра «Змейка». Язык: C#. Проект: .NET Framework 4.8.','', 'Каждый DOCX содержит титульный лист, цель, теоретическое обоснование, описание реализации и вывод.','']
for n,title,*_ in items: md.append(f'- ЛР {n}: {title} — `reports/Отчет_ЛР{n:02d}_Вариант10_CSharp.docx`')
